#!/usr/bin/env python3
# Generated by Phase: IMPLEMENT | Feature: #160
"""check-design-sections — design.md has one section map, the template's (#160). META-ONLY.

The headings of .context/templates/architect/design_template.md are the map. Scans the tracked text files
under .claude/ and .context/templates/ (the two trees that reach a project) and fails when:
  - a reference `design.md § X` (or `design § X`, `design.md Section N`, and every `+ § Y` / `/ § Y` chained
    after it) cites a section by number, or names a section the template does not have;
  - a GCD sub-section is cited by number (`§ 7.4`, `Section 7.8` — that numbering exists only in design.md);
  - a reader's section lookup (`READ(design.md, "X")`, `gcd_section["X"]`) names a section the template does not have;
  - a writer emits a design.md heading the template does not have (`WRITE design.md "## X"`,
    `APPEND_SECTION(design.md, "## X"`);
  - a template heading has no writer — no writer file names it (`§ X`, or a `# X` heading of its protocol);
  - a contract path names a directory by feature id (`rules/contract-first-policy.md` § Directory Namespacing:
    the id lives in `x-feature-id` and `feature_map.md`).
A section name is the heading text without its trailing `(…)` and `→ consumer` tags. History is not rewritten:
the governance manifest and changelogs are not scanned.

Usage: check-design-sections.py [--root DIR]      exit 0 ok · 1 a finding (file:line listed) · 2 infra
"""
from __future__ import annotations

import re
import subprocess
import sys
from pathlib import Path

ROOTS = (".claude/", ".context/templates/")
TEMPLATE = ".context/templates/architect/design_template.md"
WRITERS = (".claude/instructions/Factory-blueprint-design.instructions.md",
           ".claude/instructions/Factory-blueprint-validation.instructions.md",
           ".claude/instructions/Factory-blueprint-refine.instructions.md",
           ".claude/commands/blueprint.md",
           ".claude/skills/factory-codebase-inventory/SKILL.md")
HISTORY = re.compile(r"(^|/)(governance_versions\.json|CHANGELOG[^/]*)$")
HEADING = re.compile(r"^#{2,3} (?!\{\{)(.+?)\s*$")
TAGS = re.compile(r"\s+(?:\([^()]*\)|→ (?:REVIEW|security|workers|IMPLEMENT|N/A)\b.*)$")
ANCHOR = re.compile(r"(?<![\w/-])design(?:\.md)?`?\s*(?=§|Sections?\s+\d)")
CHAIN = re.compile(r"\s*(?:[+/,]|and|or)?\s*`?(?:§§?|Sections?(?=\s+\d))\s*")
NUMBER = re.compile(r"\d+(?:\.\d+)*[a-z]?(?:\s*/\s*\d+(?:\.\d+)*)*")
EMITTED = re.compile(r"""(?:WRITE design\.md|APPEND_SECTION\(design\.md,)\s*["']#{2,3} ([^"']+)["']""")
GCD_NUMBER = re.compile(r"(?:§ ?|Section )7\.\d")
LOOKUP = re.compile(r'(?:READ\((?:"[^"]*)?design\.md"?,\s*|gcd_section\[)"(?:§ |#{2,3} )?([^"]+)"')
FEATURE_DIR = re.compile(r"contracts/[^\s`\"')]*(?:FEAT-XXX|FEAT-\d+|\{\{?FEATURE_ID\}?\}|\{\{?ID\}?\}|\{FEAT_ID\}|\{feature_id\})")


def name_of(heading: str) -> str:
    prev = None
    while prev != heading:
        prev, heading = heading, TAGS.sub("", heading).strip()
    return heading


def section_map(root: Path) -> list[str]:
    text = (root / TEMPLATE).read_text(encoding="utf-8")
    body = text.split("```markdown", 1)[1] if "```markdown" in text else text
    names = [name_of(m.group(1)) for m in map(HEADING.match, body.splitlines()) if m]
    if not names:
        raise RuntimeError(f"{TEMPLATE} declares no section heading")
    return names


def resolves(ref: str, names: list[str]) -> str | None:
    """The longest section name `ref` opens with, ending at a word boundary (`Data Modelling` is not `Data Model`)."""
    return next((n for n in sorted(names, key=len, reverse=True) if re.match(re.escape(n) + r"(?![\w-])", ref)), None)


def references(rel: str, line: str, n: int, names: list[str]) -> list[str]:
    out = []
    for a in ANCHOR.finditer(line):
        pos = a.end()
        while (m := CHAIN.match(line, pos)) and m.end() > pos:
            ref = line[m.end():]
            num = NUMBER.match(ref)
            if num:
                out.append(f"{rel}:{n}: design.md § {num.group(0)} — cite the section by name (`design.md § <Heading>`), never by number")
                pos = m.end() + num.end()
                continue
            hit = resolves(ref, names)
            if not hit:
                out.append(f"{rel}:{n}: design.md § {ref[:40].strip()}… — no such section in {TEMPLATE}")
                break
            pos = m.end() + len(hit)
    return out


def scan(root: Path) -> list[str]:
    names = section_map(root)
    files = subprocess.run(["git", "-C", str(root), "ls-files", "--", *ROOTS], capture_output=True, text=True, check=True).stdout.split()
    findings, writers_text = [], ""
    for rel in files:
        if HISTORY.search(rel):
            continue
        try:
            text = (root / rel).read_text(encoding="utf-8")
        except (UnicodeDecodeError, FileNotFoundError):
            continue
        if rel in WRITERS:
            writers_text += text + "\n"
        for n, line in enumerate(text.splitlines(), 1):
            findings += references(rel, line, n, names)
            findings += [f"{rel}:{n}: `{m.group(0)}` — a GCD sub-section cited by number; cite it by name (`design.md § <Heading>`)"
                         for m in GCD_NUMBER.finditer(line)]
            findings += [f"{rel}:{n}: looks up `{m.group(1)}` — a design.md section the template does not have"
                         for m in LOOKUP.finditer(line) if not resolves(m.group(1), names)]
            findings += [f"{rel}:{n}: emits `{m.group(1)}` — a design.md heading the template does not have"
                         for m in EMITTED.finditer(line) if not resolves(m.group(1), names)]
            findings += [f"{rel}:{n}: `{m.group(0)}` — a contract directory named by feature id (rules/contract-first-policy.md "
                         f"§ Directory Namespacing: locate it through `feature_map.md` / `x-feature-id`)" for m in FEATURE_DIR.finditer(line)]
    findings += [f"{TEMPLATE}: `{name}` — no writer names this section ({', '.join(Path(w).name for w in WRITERS)})"
                 for name in names if not re.search(r"(?:§ |# )" + re.escape(name) + r"(?![\w-])", writers_text)]
    return findings


def main(argv: list[str]) -> int:
    root = Path(argv[argv.index("--root") + 1]).resolve() if "--root" in argv else Path(__file__).resolve().parent.parent
    try:
        findings = scan(root)
    except (RuntimeError, subprocess.CalledProcessError, OSError, IndexError) as e:
        print(f"check-design-sections: could not scan ({e})", file=sys.stderr)
        return 2
    for f in findings:
        print(f"  ✗ {f}")
    if findings:
        print(f"[FAIL] check-design-sections: {len(findings)} finding(s) — design.md has one section map, the template's")
        return 1
    print(f"[OK] check-design-sections: every design.md section cited by name resolves to the template; every heading has a writer")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
